import React, { useState, useEffect } from 'react';
import {
    Box,
    Button,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField,
    Paper,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    IconButton,
    Typography,
    Alert,
    CircularProgress,
} from '@mui/material';
import {
    Edit as EditIcon,
    Delete as DeleteIcon,
    Add as AddIcon,
} from '@mui/icons-material';
import { getSchools, createSchool, updateSchool, deleteSchool } from '../services/schools';

const SchoolManagement = () => {
    const [schools, setSchools] = useState([]);
    const [open, setOpen] = useState(false);
    const [editingSchool, setEditingSchool] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        address: '',
    });

    useEffect(() => {
        fetchSchools();
    }, []);

    const fetchSchools = async () => {
        try {
            setLoading(true);
            setError('');
            console.log('Fetching schools...');
            const schoolsData = await getSchools();
            console.log('Schools data:', schoolsData);
            setSchools(schoolsData);
        } catch (error) {
            console.error('Error fetching schools:', error);
            setError(error.message || 'Failed to fetch schools');
        } finally {
            setLoading(false);
        }
    };

    const handleOpen = (school = null) => {
        if (school) {
            setEditingSchool(school);
            setFormData({
                name: school.name,
                description: school.description || '',
                address: school.address || '',
            });
        } else {
            setEditingSchool(null);
            setFormData({
                name: '',
                description: '',
                address: '',
            });
        }
        setOpen(true);
    };

    const handleClose = () => {
        setOpen(false);
        setEditingSchool(null);
        setFormData({
            name: '',
            description: '',
            address: '',
        });
    };

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value,
        });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            setError('');
            if (editingSchool) {
                await updateSchool(editingSchool.id, formData);
            } else {
                await createSchool(formData);
            }
            handleClose();
            fetchSchools();
        } catch (error) {
            console.error('Error saving school:', error);
            setError(error.message || 'Failed to save school');
        }
    };

    const handleDelete = async (id) => {
        if (window.confirm('Are you sure you want to delete this school?')) {
            try {
                setError('');
                await deleteSchool(id);
                fetchSchools();
            } catch (error) {
                console.error('Error deleting school:', error);
                setError(error.message || 'Failed to delete school');
            }
        }
    };

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    return (
        <Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
                <Typography variant="h4" component="h1">
                    School Management
                </Typography>
                <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => handleOpen()}
                >
                    Add School
                </Button>
            </Box>

            {error && (
                <Alert severity="error" sx={{ mb: 2 }}>
                    {error}
                </Alert>
            )}

            <TableContainer component={Paper}>
                <Table>
                    <TableHead>
                        <TableRow>
                            <TableCell>Name</TableCell>
                            <TableCell>Description</TableCell>
                            <TableCell>Address</TableCell>
                            <TableCell>Actions</TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {schools.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={4} align="center">
                                    No schools found
                                </TableCell>
                            </TableRow>
                        ) : (
                            schools.map((school) => (
                                <TableRow key={school.id}>
                                    <TableCell>{school.name}</TableCell>
                                    <TableCell>{school.description}</TableCell>
                                    <TableCell>{school.address}</TableCell>
                                    <TableCell>
                                        <IconButton
                                            color="primary"
                                            onClick={() => handleOpen(school)}
                                        >
                                            <EditIcon />
                                        </IconButton>
                                        <IconButton
                                            color="error"
                                            onClick={() => handleDelete(school.id)}
                                        >
                                            <DeleteIcon />
                                        </IconButton>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </TableContainer>

            <Dialog open={open} onClose={handleClose}>
                <DialogTitle>
                    {editingSchool ? 'Edit School' : 'Add New School'}
                </DialogTitle>
                <DialogContent>
                    <Box component="form" onSubmit={handleSubmit} sx={{ mt: 2 }}>
                        <TextField
                            fullWidth
                            label="School Name"
                            name="name"
                            value={formData.name}
                            onChange={handleChange}
                            margin="normal"
                            required
                        />
                        <TextField
                            fullWidth
                            label="Description"
                            name="description"
                            value={formData.description}
                            onChange={handleChange}
                            margin="normal"
                            multiline
                            rows={3}
                        />
                        <TextField
                            fullWidth
                            label="Address"
                            name="address"
                            value={formData.address}
                            onChange={handleChange}
                            margin="normal"
                        />
                    </Box>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleClose}>Cancel</Button>
                    <Button onClick={handleSubmit} variant="contained">
                        {editingSchool ? 'Update' : 'Add'}
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default SchoolManagement;
